<script setup lang="ts">import AppIcon from '@/Components/AppIcon.vue';import InputError from '@/Components/InputError.vue';import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';import{Head,useForm}from'@inertiajs/vue3';const props=defineProps<{settings:any}>();const form=useForm({...props.settings});</script>
<template><Head title="Paramètres"/><AuthenticatedLayout><template #header><div><p class="dw-page-kicker">Configuration</p><h1 class="dw-page-title">Paramètres</h1><p class="dw-page-description">Personnalisez l’identité et les règles opérationnelles de la bibliothèque.</p></div></template><div v-if="$page.props.flash?.success" class="mb-5 rounded-md bg-emerald-50 p-4 text-sm font-bold text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300">{{$page.props.flash.success}}</div><form class="space-y-6" @submit.prevent="form.patch(route('settings.update'),{preserveScroll:true})"><section class="dw-card overflow-hidden"><div class="flex gap-4 border-b border-gray-200 p-5 dark:border-gray-900"><span class="flex h-11 w-11 items-center justify-center rounded-lg bg-primary-50 text-primary-600 dark:bg-primary-950"><AppIcon name="settings" class="h-5 w-5"/></span><div><h2 class="font-heading font-bold text-slate-700">Identité de la bibliothèque</h2><p class="mt-1 text-xs text-slate-500 dark:text-slate-400">Informations utilisées dans l’administration et les documents.</p></div></div><div class="grid gap-5 p-5 md:grid-cols-2"><div><label class="mb-2 block text-sm">Nom de la bibliothèque *</label><input v-model="form.library_name" class="dw-field"/><InputError :message="form.errors.library_name"/></div><div><label class="mb-2 block text-sm">Établissement *</label><input v-model="form.institution_name" class="dw-field"/><InputError :message="form.errors.institution_name"/></div><div><label class="mb-2 block text-sm">E-mail de contact</label><input v-model="form.contact_email" type="email" class="dw-field"/><InputError :message="form.errors.contact_email"/></div><div><label class="mb-2 block text-sm">Téléphone</label><input v-model="form.contact_phone" class="dw-field"/><InputError :message="form.errors.contact_phone"/></div></div></section><section class="dw-card overflow-hidden"><div class="flex gap-4 border-b border-gray-200 p-5 dark:border-gray-900"><span class="flex h-11 w-11 items-center justify-center rounded-lg bg-amber-50 text-amber-600 dark:bg-amber-950"><AppIcon name="loans" class="h-5 w-5"/></span><div><h2 class="font-heading font-bold text-slate-700">Règles opérationnelles</h2><p class="mt-1 text-xs text-slate-500 dark:text-slate-400">Ces valeurs sont appliquées immédiatement au comptoir.</p></div></div><div class="grid gap-5 p-5 md:grid-cols-2"><div><label class="mb-2 block text-sm">Durée de prêt par défaut</label><div class="relative"><input v-model="form.default_loan_days" type="number" min="1" max="90" class="dw-field pe-16"/><span class="absolute end-4 top-3 text-xs text-slate-500 dark:text-slate-400">jours</span></div><InputError :message="form.errors.default_loan_days"/></div><div><label class="mb-2 block text-sm">Livres maximum par prêt</label><input v-model="form.max_books_per_loan" type="number" min="1" max="20" class="dw-field"/><InputError :message="form.errors.max_books_per_loan"/></div><div><label class="mb-2 block text-sm">Fermeture du scanner après inactivité</label><div class="relative"><input v-model="form.scanner_inactivity_seconds" type="number" min="10" max="180" class="dw-field pe-20"/><span class="absolute end-4 top-3 text-xs text-slate-500 dark:text-slate-400">secondes</span></div><InputError :message="form.errors.scanner_inactivity_seconds"/></div><div><label class="mb-2 block text-sm">Validité d’une carte</label><div class="relative"><input v-model="form.card_validity_months" type="number" min="1" max="60" class="dw-field pe-16"/><span class="absolute end-4 top-3 text-xs text-slate-500 dark:text-slate-400">mois</span></div><InputError :message="form.errors.card_validity_months"/></div></div></section><div class="flex justify-end"><button class="dw-btn-primary" :disabled="form.processing">{{form.processing?'Enregistrement…':'Enregistrer les paramètres'}}</button></div></form></AuthenticatedLayout></template>
